
  .welcome-page {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    background: url('../assets/welcome/welcome-bg-h5.png')no-repeat center center;
    background-size: cover;
    min-height: 100vh;
    width: 100%;
    padding: 50px 0;
    .promotionlist {
      justify-content: center;
      align-items: center;
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      grid-gap: 10px;
      padding: 40px 20px 0;
      img {
        width: 100%;
        cursor: pointer;
      }
    }
    a {
      width: 100%;
      display: flex;
      justify-content: center;
      align-items: center;
      background: url('../assets/welcome/button.png')no-repeat center center;
      background-size: cover;
      color: #000000;
      font-size: 35px;
      line-height: 77px;
      max-width: 300px;
        margin: 20px auto;
      padding-bottom: 15px;
    }
    .logo {
      display: flex;
      justify-content: center;
      align-items: center;
      max-width: 400px;
      img {
        width: 100%;
      }
    }
    .slogan {
      color: #ffffff;
      text-transform: uppercase;
      font-weight: bold;
      text-align: center;
        font-size: 20px;
        margin: 0 10px 60px;
    }
  }
